const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const code = fs.readFileSync(require('node:path').join(__dirname,'../app/src/main/assets/aktu_probe.js'),'utf8');
const row = (text) => ({innerText:text,textContent:text,closest(q){return q==='table'?table:null}});
const head=row('Code Name Type Internal External Back Paper Grade'), marked=row('ABC101 Chemistry Theory 22 45 -- B');
const table={offsetWidth:100,getClientRects:()=>[{}],querySelectorAll(q){return q==='tr'?[head,marked]:[]},innerText:'Code Name Type Internal External Back Paper Grade ABC101 Chemistry Theory 22 45 -- B',textContent:''};
const page={querySelectorAll(q){return q==='table'?[table]:[]}};
const parse=()=>JSON.parse(vm.runInNewContext(code,{document:page,Math}));
const v=parse();assert.equal(v.ready,true);assert.ok(v.signature);assert.equal(v.signature,parse().signature);
page.querySelectorAll=()=>[];assert.equal(parse().ready,false);
console.log('AKTU loaded-scorecard detection tests passed');

